async page=>{
 const base=new URL(page.url()).origin;await page.goto(base+'/');await page.getByText('LOCAL NEAR SANDBOX',{exact:true}).waitFor();
 await page.goto(base+'/settings/wallets');await page.locator('form[data-live-form=connect-test]').waitFor();await page.locator('form[data-live-form=connect-test] select').selectOption('seller.sandbox');await page.locator('form[data-live-form=connect-test] button[type=submit]').click();await page.locator('dialog button[value=approve]').click();await page.waitForFunction(()=>!document.body.classList.contains('connected-busy'));
 await page.goto(base+'/host/assets/new');await page.locator('[data-live-action=start-capture]').click();await page.waitForURL('**/host/capture/*');const captureUrl=await page.locator('input[readonly]').inputValue();
 const camera=await page.context().newPage();await camera.goto(captureUrl);await camera.locator('[name=photo]').setInputFiles({name:'synthetic-vehicle.png',mimeType:'image/png',buffer:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScLbtAAAAABJRU5ErkJggg==','base64')});await camera.locator('form[data-live-form=capture-photo] button[type=submit]').click();await camera.getByRole('heading',{name:'Your photo is ready.'}).waitFor();await camera.close();
 await page.getByRole('button',{name:'Check photo status',exact:true}).click();await page.waitForFunction(()=>!document.body.classList.contains('connected-busy'));await page.locator('[data-live-action=use-capture]').click();await page.locator('[name=method]').selectOption('manual');await page.locator('[name=title]').fill('Private camera handoff');await page.locator('[name=city]').fill('Bucharest');await page.locator('[name=description]').fill('Private reference photo captured in a separate browser tab.');await page.locator('form[data-live-form=asset-create] button[type=submit]').click();await page.waitForURL('**/review');await page.locator('[name=reviewed]').check();await page.locator('form[data-live-form=asset-edit] button[type=submit]').click();await page.waitForFunction(()=>!document.body.classList.contains('connected-busy'));if(await page.locator('#connected-notice.orange:visible').count())throw Error(await page.locator('#connected-notice').textContent());
 await page.goto(base+'/settings/profile');await page.locator('[name=displayName]').fill('Qualified Space Owner');await page.locator('form[data-live-form=profile] button[type=submit]').click();await page.waitForFunction(()=>!document.body.classList.contains('connected-busy'));await page.reload();await page.getByText('Qualified Space Owner',{exact:false}).first().waitFor();
 return {privateCaptureHandoff:true,profilePersisted:true};
}
